import re

from moler.exceptions import ParsingDone, CommandFailure

from ta_moler.cmd.cFZC.genericcfzc import GenericcFZCCommand

__author__ = 'Bartosz Odziomek'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'bartosz.odziomek@nokia.com'


class Transconf_show(GenericcFZCCommand):
    """Transconf_show command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Transconf_show command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the start command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Transconf_show, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret['RESULT'] = {}
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "transconf show"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_blank_output_line(line)
                self._start_parse_ipsec_in_use(line)
            except ParsingDone:
                pass
        return super(Transconf_show, self).on_new_line(line, is_full_line)

    def _start_parse_ipsec_in_use(self, line):
        """
        Start parsing methods if parameter options = 'ipsec-in-use'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "ipsec-in-use":
            self._parse_ipsec_in_use(line)

    _re_ipsec_in_use = re.compile(r"^(?P<FLAG>\d+)$")

    def _parse_ipsec_in_use(self, line):
        """
        Create dictionary with ipsec-in-use details:.

        'ipsec-in-use'.
        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(Transconf_show._re_ipsec_in_use, line):
            flag = self._regex_helper.group("FLAG")
            self.current_ret['RESULT'] = {"ipsec_in_use_flag": flag}
            raise ParsingDone

    _re_blank_output = re.compile(r"^(?P<ERROR>\s+)$")

    def _parse_blank_output_line(self, line):
        """
        Raise commandfailure when find line with blank output line.

        :param line: Line from device.
        :return: None but raises CommandFailure.
        """
        if self._regex_helper.search(Transconf_show._re_blank_output, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone


COMMAND_OUTPUT = """
trmsg#transconf show ipsec-in-use
0
trmsg#"""

COMMAND_KWARGS = {
    "options": "ipsec-in-use"
}

COMMAND_RESULT = {
    'RESULT': {'ipsec_in_use_flag': '0'}
}
